162	/**
163	 * @internal
164	 */
165	export function createMiddlewareFactory<
166	  TConfig extends AnyRootConfig,
167	  TInputIn = unknown,
168	>() {
169	  function createMiddlewareInner<TNewParams extends ProcedureParams>(
170	    middlewares: MiddlewareFunction<any, any>[],
171	  ): MiddlewareBuilder<deriveParamsFromConfig<TConfig, TInputIn>, TNewParams> {
172	    return {
173	      _middlewares: middlewares,
174	      unstable_pipe(middlewareBuilderOrFn) {
175	        const pipedMiddleware =
176	          '_middlewares' in middlewareBuilderOrFn
177	            ? middlewareBuilderOrFn._middlewares
178	            : [middlewareBuilderOrFn];
179	
180	        return createMiddlewareInner([
181	          ...(middlewares as any),
182	          ...pipedMiddleware,
183	        ]);
184	      },
185	    };
186	  }
187	
188	  function createMiddleware<TNewParams extends ProcedureParams>(
189	    fn: MiddlewareFunction<
190	      deriveParamsFromConfig<TConfig, TInputIn>,
191	      TNewParams
192	    >,
193	  ): MiddlewareBuilder<deriveParamsFromConfig<TConfig, TInputIn>, TNewParams> {
194	    return createMiddlewareInner([fn]);
195	  }
196	
197	  return createMiddleware;
198	}
