import {
  inferRouterInputs,
  inferRouterOutputs,
  initTRPC,
  experimental_standaloneMiddleware,
} from '@trpc/server';
import type { Overwrite, UnsetMarker } from '@trpc/server/core/internals/utils';
import { z } from 'zod';

// Print a type via a deliberate assignment error.
declare const SHOW: unique symbol;
type Show<T> = { [SHOW]: T };
declare function show<T>(): Show<T>;

// ---- pure type-level probes on Overwrite ----
const o1: 'Overwrite<string,string>' = show<Overwrite<string, string>>();
const o2: 'Overwrite<{a:1},{a:2,b:3}>' = show<Overwrite<{ a: 1 }, { a: 2; b: 3 }>>();
const o3: 'Overwrite<{a:1},undefined>' = show<Overwrite<{ a: 1 }, undefined>>();
const o4: 'Overwrite<{a:string}|undefined, same>' = show<
  Overwrite<{ a: string } | undefined, { a: string } | undefined>
>();
type Branded = string & z.BRAND<'X'>;
const o5: 'Overwrite<Branded,Branded>' = show<Overwrite<Branded, Branded>>();
const o5b: 'Branded extends object' = show<Branded extends object ? 'yes' : 'no'>();
const o6: 'Overwrite<any,any>' = show<Overwrite<any, any>>();
const o7: 'Overwrite<{a:1},any>' = show<Overwrite<{ a: 1 }, any>>();
const o8: 'Overwrite<{a:1},unknown>' = show<Overwrite<{ a: 1 }, unknown>>();
const o9: 'Overwrite<{a:1},never>' = show<Overwrite<{ a: 1 }, never>>();
const o10: 'Overwrite<string,never>' = show<Overwrite<string, never>>();
const o11: 'Overwrite<UnsetMarker,{a:1}>' = show<Overwrite<UnsetMarker, { a: 1 }>>();
const o12: 'Overwrite<UnsetMarker,string>' = show<Overwrite<UnsetMarker, string>>();
const o13: 'Overwrite<string[],string[]>' = show<Overwrite<string[], string[]>>();
const o14: 'Overwrite<Date,Date>' = show<Overwrite<Date, Date>>();
const o15: 'Overwrite<{a:1}, null>' = show<Overwrite<{ a: 1 }, null>>();
const o16: 'Overwrite<{a:1}|string, {b:2}>' = show<Overwrite<{ a: 1 } | string, { b: 2 }>>();
const o17: 'Overwrite<number, string>' = show<Overwrite<number, string>>();

// ---- end-to-end procedure inference ----
type Ctx = { user: { id: string } | null; db: string };
const t = initTRPC.context<Ctx>().create();
const passthrough = t.middleware((opts) => opts.next());

const router = t.router({
  str: t.procedure.input(z.string()).use(passthrough).query(({ input }) => input),
  num: t.procedure.input(z.number()).use(passthrough).query(({ input }) => input),
  branded: t.procedure
    .input(z.string().brand('X'))
    .use(passthrough)
    .query(({ input }) => input),
  brandedNoMw: t.procedure.input(z.string().brand('X')).query(({ input }) => input),
  optObj: t.procedure
    .input(z.object({ a: z.string() }).optional())
    .use(passthrough)
    .query(({ input }) => input),
  arr: t.procedure.input(z.array(z.string())).use(passthrough).query(({ input }) => input),
  date: t.procedure.input(z.date()).use(passthrough).query(({ input }) => input),
  union: t.procedure
    .input(z.union([z.object({ a: z.string() }), z.object({ b: z.number() })]))
    .use(passthrough)
    .query(({ input }) => input),
  strTwoMw: t.procedure
    .input(z.string())
    .use(passthrough)
    .use(passthrough)
    .query(({ input }) => input),
  ctxUndef: t.procedure
    .use(({ ctx, next }) => next({ ctx: ctx.user ? { user: ctx.user } : undefined }))
    .query(({ ctx }) => ctx),
  ctxNull: t.procedure
    .use(({ ctx, next }) => next({ ctx: ctx.user ? { user: ctx.user } : null }))
    .query(({ ctx }) => ctx),
  ctxNarrow: t.procedure
    .use(({ ctx, next }) => {
      if (!ctx.user) throw new Error('x');
      return next({ ctx: { user: ctx.user } });
    })
    .query(({ ctx }) => ctx),
  concatStr: t.procedure
    .unstable_concat(t.procedure.input(z.string()))
    .query(({ input }) => input),
  concatObj: t.procedure
    .unstable_concat(t.procedure.input(z.object({ a: z.string() })))
    .query(({ input }) => input),
});

type In = inferRouterInputs<typeof router>;
type Out = inferRouterOutputs<typeof router>;

const e1: 'In.str' = show<In['str']>();
const e2: 'In.num' = show<In['num']>();
const e3: 'In.branded' = show<In['branded']>();
const e3b: 'In.brandedNoMw' = show<In['brandedNoMw']>();
const e4: 'In.optObj' = show<In['optObj']>();
const e5: 'In.arr' = show<In['arr']>();
const e6: 'In.date' = show<In['date']>();
const e7: 'In.union' = show<In['union']>();
const e8: 'In.strTwoMw' = show<In['strTwoMw']>();
const e9: 'Out.ctxUndef' = show<Out['ctxUndef']>();
const e10: 'Out.ctxNull' = show<Out['ctxNull']>();
const e11: 'Out.ctxNarrow' = show<Out['ctxNarrow']>();
